from pptx import Presentation
from pptx.enum.shapes import MSO_SHAPE_TYPE

# Load the processed presentation
prs = Presentation('/root/Awesome-Agent-Papers_processed.pptx')

print(f"Number of slides: {len(prs.slides)}")
print(f"Slide dimensions: {prs.slide_width.inches} x {prs.slide_height.inches} inches")
print()

# Verify each slide
for slide_idx, slide in enumerate(prs.slides):
    print(f"=== Slide {slide_idx + 1} ===")
    for shape in slide.shapes:
        if shape.shape_type == MSO_SHAPE_TYPE.TEXT_BOX and shape.text.strip():
            print(f"  Paper Title TEXT_BOX: {shape.text[:60]}...")
            print(f"    Position: left={shape.left.inches:.2f}, top={shape.top.inches:.2f}")
            print(f"    Size: width={shape.width.inches:.2f}, height={shape.height.inches:.2f}")
            if shape.has_text_frame:
                for para in shape.text_frame.paragraphs:
                    for run in para.runs:
                        color = run.font.color.rgb if run.font.color.rgb else "None"
                        print(f"    Font: name={run.font.name}, size={run.font.size.pt if run.font.size else 'None'}pt, bold={run.font.bold}, color={color}")
        elif hasattr(shape, 'text') and shape.text.strip():
            if "Reference" in shape.text or shape.text.strip() in ["Foam-Agent", "ReAct", "MAST", "MultiAgentBench", "Awesome-Agent-Papers"]:
                print(f"  Title/Header: {shape.text[:50]}...")
            elif len(shape.text) > 100:
                # This might be the reference list
                print(f"  Content (Reference list preview):")
                lines = shape.text.split('\n')
                for line in lines[:5]:
                    print(f"    {line[:70]}...")
    print()
EOF
